-- ============================================
-- MATERIAS: materia jurídica del informe (contrataciones, personal, presupuesto...)
-- ============================================
CREATE TABLE IF NOT EXISTS "MATERIAS" (
    "ID_MATERIA" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_MATERIAS" PRIMARY KEY,
    "NOMBRE" VARCHAR(150) NOT NULL CONSTRAINT "UQ_MATERIAS_NOMBRE" UNIQUE,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);
